package com.gestionmedica.service;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.gestionmedica.exception.ApiException; import com.gestionmedica.model.Models.*; import com.gestionmedica.persistence.entity.PrescriptionEntity; import com.gestionmedica.persistence.repository.PrescriptionRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*;
@Service public class PrescriptionService {
 private final PrescriptionRepository prescriptions; private final ObjectMapper json;
 public PrescriptionService(PrescriptionRepository prescriptions,ObjectMapper json){this.prescriptions=prescriptions;this.json=json;}
 @Transactional public Prescription create(String patientId,List<Medication> medications,List<String> allergies){for(Medication m:medications)if(allergies.stream().anyMatch(a->m.name().toLowerCase().contains(a.toLowerCase())||a.toLowerCase().contains(m.name().toLowerCase())))throw ApiException.badRequest("Medicamento incompatible con una alergia registrada: "+m.name());Prescription p=new Prescription(UUID.randomUUID().toString(),patientId,List.copyOf(medications),LocalDate.now().toString());try{prescriptions.save(new PrescriptionEntity(p.id(),patientId,p.createdAt(),json.writeValueAsString(p.medications())));return p;}catch(Exception e){throw new IllegalStateException("No se pudo guardar la prescripción",e);}}
 @Transactional(readOnly=true) public List<Prescription> forPatient(String id){return prescriptions.findByPatientId(id).stream().map(p->{try{return new Prescription(p.getId(),p.getPatientId(),json.readValue(p.getMedicationsJson(),new TypeReference<List<Medication>>(){}),p.getCreatedAt());}catch(Exception e){throw new IllegalStateException("No se pudo leer la prescripción",e);}}).toList();}
}
